using System;using System.Linq;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using UnityEngine.SceneManagement;using Codice.Characters;using Codice.Mechanics;using Codice.Presentation;using Codice.UI;
public static class VerifyClassRuntime{
 public static async Task<string> Run(){foreach(PlayerClass role in Enum.GetValues(typeof(PlayerClass))){var old=RunDirector.Instance?RunDirector.Instance.Player:null;typeof(RunNavigation).GetField("<SelectedClass>k__BackingField",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,role);SceneManager.LoadScene("SalaPruebas");for(int i=0;i<150&&(!RunDirector.Instance||!RunDirector.Instance.Player||RunDirector.Instance.Player==old);i++)await Task.Delay(100);await Task.Delay(250);var p=RunDirector.Instance.Player;var a=p.GetComponent<ActorPresentation>();if(!a.Body||!a.Body.isHuman||!a.Body.GetComponentsInChildren<SkinnedMeshRenderer>().Any(x=>UnityEditor.AssetDatabase.GetAssetPath(x.sharedMesh).Contains("CindersDetailed")))throw new Exception("Model not applied "+role);p.enabled=false;p.GetComponent<PlayerCombat>().enabled=false;p.SetNarrativeControlsBlocked(false);p.SprintRequested=false;if(!p.Sprinting)throw new Exception("Run requires button "+role);var cc=p.GetComponent<CharacterController>();cc.enabled=false;p.transform.position=new Vector3(0,1,0);cc.enabled=true;for(int j=0;j<20;j++){p.SimulateMotor(Vector3.forward,false,.02f);await Task.Delay(20);}if(p.MotorVelocity.magnitude<3.8f)throw new Exception("Run too slow "+role+" speed="+p.MotorVelocity.magnitude);foreach(var name in new[]{"Movement","Dash",role==PlayerClass.Berserker?"DualSlice":"SwordCombo1","Conjure"}){a.Play(name,.42f,true);await Task.Delay(100);if(!a.Body.HasState(0,Animator.StringToHash(name)))throw new Exception("State missing "+role+" "+name);}Debug.Log("[ClassModelTest] PASS "+role+" model, run without sprint key, action states");}return "PASS 6 class models in Play Mode, automatic run, attack/cast/roll states";}
}


